fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2 - 20;
    let r: i32 = if w < h { w / 3 } else { h / 3 };
    host::display::clear(0x0a0a0e);
    let mut i: i32 = 0;
    while i < 32 {
        let p: i32 = i * 100 / 32;
        let col: i32 = if p < 45 { 0x40b0ff } else { if p < 75 { 0xffb040 } else { 0x60d080 } };
        let x: i32 = cx + sv(i) * r / 127;
        let y: i32 = cy - sv(i + 8) * r / 127;
        host::display::fill_rect(x - 8, y - 8, 17, 17, col);
        i = i + 1;
    }
    let ly: i32 = h - 70;
    host::display::fill_rect(20, ly, 12, 12, 0x40b0ff);
    host::display::draw_string(38, ly, "A", 0xc0c0c0, 2);
    host::display::draw_number(58, ly, 45, 0xc0c0c0, 2);
    host::display::fill_rect(110, ly, 12, 12, 0xffb040);
    host::display::draw_string(128, ly, "B", 0xc0c0c0, 2);
    host::display::draw_number(148, ly, 30, 0xc0c0c0, 2);
    host::display::fill_rect(200, ly, 12, 12, 0x60d080);
    host::display::draw_string(218, ly, "C", 0xc0c0c0, 2);
    host::display::draw_number(238, ly, 25, 0xc0c0c0, 2);
    host::display::present();
}
